 18	} from "./openai-compat";
 19	import { isExternalHttpUrl } from "./view";
 20	
 21	/** Shared iframe-side runtime for every Lobu MCP App bundle. */
 22	
 23	type ToolArgs = Record<string, unknown>;
 24	type ViewStateValue = boolean | number | string;
 25	type McpAppViewState = Record<string, ViewStateValue>;
 26	
 27	interface McpAppApi<T> {
 28		/** Server-authored LobuViewV1 from the originating tool result. */
 29		data: T | null;
 30		/** Originating MCP tool name, supplied by the standard host context. */
 31		toolName: string | null;
 32		/** Small restored pagination/disclosure state for this exact result card. */
 33		viewState: McpAppViewState;
 34		setViewState: (key: string, value: ViewStateValue) => void;
 35		/** Ask the host to broker a standard MCP `tools/call`. */
 36		callTool: (name: string, args: ToolArgs) => Promise<void>;
 37		/** Ask the host to open an external URL via `ui/open-link`. */
 38		openLink: (href: string) => Promise<void>;
 39		/** Latest app-initiated tool result; `seq` bumps so effects react to retries. */
 40		lastResult: { isError: boolean; seq: number } | null;
 41		/** True only inside Lobu's same-origin SPA parent, never in an external host. */
 42		allowSpaHostedViews: boolean;
 43	}
 44	
 45	const McpAppContext = createContext<McpAppApi<unknown>>({
 46		data: null,
 47		toolName: null,
 48		viewState: {},
 49		setViewState: () => {},
 50		callTool: async () => {},
 51		openLink: async () => {},
 52		lastResult: null,
 53		allowSpaHostedViews: false,
 54	});
 55	
 56	/** Typed accessor for the host bridge inside a bundle's card component. */
 57	export function useMcpApp<T>(): McpAppApi<T> {
 58		return useContext(McpAppContext) as McpAppApi<T>;
 59	}
 60	
 61	const isEmbedded = window.parent !== window;
 62	const OPENAI_SET_GLOBALS_EVENT = "openai:set_globals";
 63	
 64	type OpenAiCompatWindow = Window & { openai?: unknown };
 65	type OpenAiSetGlobalsEvent = CustomEvent<{ globals?: unknown }>;
 66	
 67	function openAiCompatTargets(): OpenAiCompatWindow[] {
 68		const ownWindow = window as OpenAiCompatWindow;
 69		if (!isEmbedded) return [ownWindow];
 70		try {
 71			if (window.parent.location.origin === window.location.origin) {
 72				return [ownWindow, window.parent as OpenAiCompatWindow];
 73			}
 74		} catch {
 75			// A cross-origin parent is the standard portable MCP Apps topology.
 76		}
 77		return [ownWindow];
 78	}
 79	
 80	function currentOpenAiGlobals(targets = openAiCompatTargets()): unknown {
 81		let fallback: unknown;
 82		let metadataFallback: unknown;
 83		let widgetStateFallback: unknown;
 84		for (const target of targets) {
 85			const candidate = target.openai;
 86			if (candidate === undefined) continue;
 87			fallback ??= candidate;
 88			if (
 89				isStructuredObject(candidate) &&
 90				Object.hasOwn(candidate, "toolOutput")
 91			) {
 92				return candidate;
 93			}
 94			if (
 95				isStructuredObject(candidate) &&
 96				readOpenAiCompatSnapshot(candidate).data !== undefined
 97			) {
 98				widgetStateFallback ??= candidate;
 99			}
100			if (
101				isStructuredObject(candidate) &&
102				Object.hasOwn(candidate, "toolResponseMetadata")
103			) {
104				metadataFallback ??= candidate;
105			}
106		}
107		return widgetStateFallback ?? metadataFallback ?? fallback;
108	}
109	
110	function persistOpenAiData<T>(
111		targets: OpenAiCompatWindow[],
112		data: T | null,
113	): void {
114		for (const target of targets) {
115			if (persistOpenAiViewSnapshot(target.openai, data)) return;
116		}
117	}
118	
119	function hasSameOriginParent(): boolean {
120		if (!isEmbedded) return true;
121		try {
122			return window.parent.location.origin === window.location.origin;
123		} catch {
124			return false;
125		}
126	}
127	
128	function isStructuredObject(value: unknown): value is Record<string, unknown> {
129		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
130	}
131	
132	function hasResultData(value: unknown): value is Record<string, unknown> {
133		return isStructuredObject(value) && Object.keys(value).length > 0;
134	}
135	
136	function toolInfoFromHostContext(value: unknown): {
137		id: string | number;
138		name: string;
139	} | null {
140		if (!isStructuredObject(value) || !isStructuredObject(value.toolInfo))
