156	}
157	
158	function snapshotCapabilityFromMeta(value: unknown): string | null | undefined {
159		if (
160			!isStructuredObject(value) ||
161			!Object.hasOwn(value, "lobu/mcp-app-snapshot-capability")
162		)
163			return undefined;
164		const capability = value["lobu/mcp-app-snapshot-capability"];
165		if (typeof capability !== "string") return null;
166		const normalized = capability.trim();
167		return normalized && normalized.length <= 512 ? normalized : null;
168	}
169	
170	function restoredViewState(value: unknown): McpAppViewState {
171		if (!isStructuredObject(value)) return {};
172		return Object.fromEntries(
173			Object.entries(value).filter(
174				(entry): entry is [string, ViewStateValue] =>
175					typeof entry[1] === "boolean" ||
176					typeof entry[1] === "string" ||
177					(typeof entry[1] === "number" && Number.isFinite(entry[1])),
178			),
179		);
180	}
181	
182	function sameViewState(
183		left: McpAppViewState,
184		right: McpAppViewState,
185	): boolean {
186		const leftKeys = Object.keys(left);
187		const rightKeys = Object.keys(right);
188		return (
189			leftKeys.length === rightKeys.length &&
190			leftKeys.every((key) => left[key] === right[key])
191		);
192	}
193	
194	function resultDataFingerprint(value: unknown): string | null {
195		try {
196			return (
197				JSON.stringify(value, (_key, nested) =>
198					isStructuredObject(nested)
199						? Object.fromEntries(
200								Object.entries(nested).sort(([left], [right]) =>
201									left.localeCompare(right),
202								),
203							)
204						: nested,
205				) ?? null
206			);
207		} catch {
208			return null;
209		}
210	}
211	
212	function applyTheme(theme: "light" | "dark" | undefined): void {
213		const dark = theme
214			? theme === "dark"
215			: window.matchMedia("(prefers-color-scheme: dark)").matches;
216		document.documentElement.classList.toggle("dark", dark);
217	}
218	
219	export function Provider<T>({
220		devMock,
