246		const hasAuthoritativeResultData = useRef(false);
247		const hasCurrentLifetimeToolResult = useRef(false);
248		const hasData = useRef(data !== null);
249		const resultExplicitlyCleared = useRef(false);
250		const dataRevision = useRef(data === null ? 0 : 1);
251		const toolCallId = useRef<string | number | null>(null);
252		const toolCallName = useRef<string | null>(null);
