it("clears a displayed card on explicit null compatibility output", async () => {
	const setWidgetState = vi.fn();
	const compatParent: CompatParent = Object.assign(new EventTarget(), {
		location: { origin: window.location.origin },
		openai: {
			toolOutput: { title: "Displayed result" },
			setWidgetState,
		},
	});
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: compatParent,
	});

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data } = useMcpApp<{ title: string }>();
		return <span>{data?.title ?? "No result"}</span>;
	}

	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);
	expect(await screen.findByText("Displayed result")).toBeInTheDocument();
	await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));

	act(() => {
		compatParent.dispatchEvent(
			new CustomEvent("openai:set_globals", {
				detail: { globals: { toolOutput: null } },
			}),
		);
	});

	expect(await screen.findByText("No result")).toBeInTheDocument();
	expect(screen.queryByText("Displayed result")).not.toBeInTheDocument();
	expect(setWidgetState).toHaveBeenLastCalledWith({
		privateContent: {
			lobuViewSnapshot: { version: 1, data: null },
		},
	});
	expect(
		bridge.callServerTool.mock.calls.some(
			([request]) => request.name === "restore_lobu_app_result",
		),
	).toBe(false);

	act(() => {
		compatParent.dispatchEvent(
			new CustomEvent("openai:set_globals", {
				detail: {
					globals: {
						toolResponseMetadata: {
							mcp_tool_result: {
								_meta: {
									"lobu/mcp-app-snapshot-capability":
										"cleared-result-token",
								},
							},
						},
					},
				},
			}),
		);
	});

	expect(screen.getByText("No result")).toBeInTheDocument();
	expect(
		bridge.callServerTool.mock.calls.some(
			([request]) => request.name === "restore_lobu_app_result",
		),
	).toBe(false);
});

it("detaches the cleared host identity before a later unpaired result", async () => {
	const compatParent: CompatParent = Object.assign(new EventTarget(), {
		location: { origin: window.location.origin },
	});
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: compatParent,
	});
	bridge.hostContext = {
		toolInfo: { id: "cleared-card", tool: { name: "query_sdk" } },
	};
	bridge.callServerTool.mockImplementation(async ({ name }) => ({
		isError: false,
		...(name === "save_lobu_app_state"
			? { structuredContent: { saved: true } }
			: {}),
	}));

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data, setViewState } = useMcpApp<{ title: string }>();
		return (
			<>
				<span>{data?.title ?? "No result"}</span>
				<button
					type="button"
					onClick={() => setViewState("details.open", true)}
				>
					Expand
				</button>
			</>
		);
	}
	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);
	await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));

	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({ structuredContent: { title: "Card before clear" } });
		}
	});
	expect(await screen.findByText("Card before clear")).toBeInTheDocument();
	act(() => {
		compatParent.dispatchEvent(
			new CustomEvent("openai:set_globals", {
				detail: { globals: { toolOutput: null } },
			}),
		);
	});
	expect(await screen.findByText("No result")).toBeInTheDocument();
	act(() => {
		compatParent.dispatchEvent(
			new CustomEvent("openai:set_globals", {
				detail: {
					globals: { toolOutput: { title: "Unpaired next card" } },
				},
			}),
		);
	});
	expect(await screen.findByText("Unpaired next card")).toBeInTheDocument();

	bridge.callServerTool.mockClear();
	fireEvent.click(screen.getByRole("button", { name: "Expand" }));
	await act(
		() => new Promise((resolve) => window.setTimeout(resolve, 300)),
	);
	expect(bridge.callServerTool).not.toHaveBeenCalled();
});

