const r = await tools.exec_command({
  cmd: "cat > src/mcp-apps/_shared/host.review.test.tsx <<'EOF'
import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
  callServerTool: vi.fn(),
  connect: vi.fn().mockResolvedValue(undefined),
  hostContext: {} as Record<string, unknown>,
  listeners: new Map<string, Set<(params: unknown) => void>>(),
}));
vi.mock("@modelcontextprotocol/ext-apps", () => ({
  App: class {
    addEventListener(name: string, handler: (params: unknown) => void) {
      const handlers = bridge.listeners.get(name) ?? new Set(); handlers.add(handler); bridge.listeners.set(name, handlers);
    }
    removeEventListener() {}
    callServerTool = bridge.callServerTool;
    connect = bridge.connect;
    getHostContext() { return { theme: "light", ...bridge.hostContext }; }
    async openLink() { return { isError: false }; }
  },
  PostMessageTransport: class { async close() {} },
}));
const originalParent = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenai = Object.getOwnPropertyDescriptor(window, "openai");
function restore(name: "parent" | "openai", descriptor: PropertyDescriptor | undefined) {
  if (descriptor) Object.defineProperty(window, name, descriptor); else Reflect.deleteProperty(window, name);
}

describe("review regressions", () => {
  beforeEach(() => { vi.resetModules(); vi.clearAllMocks(); bridge.listeners.clear(); bridge.hostContext = {}; bridge.connect.mockResolvedValue(undefined); });
  afterEach(() => { restore("parent", originalParent); restore("openai", originalOpenai); });

  it("switches an id-restored card when the next result only has a capability", async () => {
    const parent = Object.assign(new EventTarget(), { location: { origin: "https://chatgpt.com" } });
    Object.defineProperty(window, "parent", { configurable: true, value: parent });
    bridge.hostContext = { toolInfo: { id: "old-card", tool: { name: "query_sdk" } } };
    bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
      if (name === "restore_lobu_app_result") {
        if (args.tool_call_id === "old-card") return { isError: false, structuredContent: { found: true, tool_name: "query_sdk", data: { title: "Old restored card" }, view_state: {} } };
        if (args.snapshot_capability === "new-token") return { isError: false, structuredContent: { found: true, tool_name: "query_sql", data: { title: "New capability card" }, view_state: {} } };
      }
      return { isError: false, structuredContent: { saved: false } };
    });
    const { Provider, useMcpApp } = await import("./host");
    function Probe() { const { data } = useMcpApp<{title:string}>(); return <span>{data?.title ?? "No result"}</span>; }
    render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
    expect(await screen.findByText("Old restored card")).toBeInTheDocument();
    act(() => { for (const handler of bridge.listeners.get("toolresult") ?? []) handler({ structuredContent: {}, _meta: { "lobu/mcp-app-snapshot-capability": "new-token" } }); });
    await waitFor(() => expect(screen.getByText("New capability card")).toBeInTheDocument());
  });

  it("restores a different host card after an explicit clear", async () => {
    const parent = Object.assign(new EventTarget(), { location: { origin: window.location.origin } });
    Object.defineProperty(window, "parent", { configurable: true, value: parent });
    bridge.hostContext = { toolInfo: { id: "old-card", tool: { name: "query_sdk" } } };
    bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
      if (name === "restore_lobu_app_result") {
        const fresh = args.tool_call_id === "new-card";
        return { isError: false, structuredContent: { found: true, tool_name: "query_sdk", data: { title: fresh ? "New restored card" : "Old restored card" }, view_state: {} } };
      }
      return { isError: false };
    });
    const { Provider, useMcpApp } = await import("./host");
    function Probe() { const { data } = useMcpApp<{title:string}>(); return <span>{data?.title ?? "No result"}</span>; }
    render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
    expect(await screen.findByText("Old restored card")).toBeInTheDocument();
    act(() => parent.dispatchEvent(new CustomEvent("openai:set_globals", { detail: { globals: { toolOutput: null } } })));
    expect(await screen.findByText("No result")).toBeInTheDocument();
    bridge.hostContext = { toolInfo: { id: "new-card", tool: { name: "query_sdk" } } };
    act(() => { for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) handler({ theme: "light" }); });
    await waitFor(() => expect(screen.getByText("New restored card")).toBeInTheDocument());
  });
});
EOF
